package com.chx.notification.infra;
import org.apache.kafka.clients.consumer.ConsumerConfig; import org.apache.kafka.common.serialization.StringDeserializer; import org.springframework.context.annotation.*; import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory; import org.springframework.kafka.core.*; import org.springframework.kafka.listener.DefaultErrorHandler; import org.springframework.util.backoff.FixedBackOff; import org.springframework.kafka.support.serializer.JsonDeserializer;
@Configuration public class KafkaConsumerConfig { @Bean ConsumerFactory<String,String> consumerFactory(org.springframework.core.env.Environment env){var p=new java.util.HashMap<String,Object>();p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG,env.getProperty("spring.kafka.bootstrap-servers","localhost:9092"));p.put(ConsumerConfig.GROUP_ID_CONFIG,"notification-service");p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG,StringDeserializer.class);p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG,StringDeserializer.class);return new DefaultKafkaConsumerFactory<>(p);}
 @Bean ConcurrentKafkaListenerContainerFactory<String,String> kafkaListenerContainerFactory(ConsumerFactory<String,String> cf){var f=new ConcurrentKafkaListenerContainerFactory<String,String>();f.setConsumerFactory(cf);f.setCommonErrorHandler(new DefaultErrorHandler(new FixedBackOff(1000L,3)));return f;} }
